#!/usr/bin/env python3
"""Regenerates docs/TESTING.md from the test names, so the catalogue never drifts from the tests.

Usage: python3 scripts/generate-test-catalog.py
"""
import pathlib
import re

ROOT = pathlib.Path(__file__).resolve().parent.parent
out = [
    "# Test catalogue",
    "",
    "Generated by `scripts/generate-test-catalog.py` from the test names - do not edit by hand.",
    "Each line is one test; together they are the specification of the system's behaviour.",
    "",
    "Run everything: `mvn clean verify` (backend), `cd frontend && npm test` (frontend) and, after",
    "`mvn -Pfullstack package`, `cd e2e && npm test` (end-to-end, in a real browser).",
    "",
    "## Backend (JUnit, `src/test/java`)",
    "",
    "Integration tests boot the whole app on H2 in MariaDB mode with the real Flyway migrations;",
    "each test runs in a rolled-back transaction. Shared helpers live in `support/`.",
    "",
]
backend_count = 0
for path in sorted((ROOT / "src/test/java").rglob("*Test.java")):
    text = path.read_text()
    cls = re.search(r'@DisplayName\("([^"]+)"\)\s*(?:@\w+(?:\([^)]*\))?\s*)*class\s+(\w+)', text)
    title = cls.group(1) if cls else path.stem
    rel = path.relative_to(ROOT).as_posix()
    tests = []
    for m in re.finditer(r'@(?:Test|ParameterizedTest(?:\(name = "([^"]+)"\))?)\s*(?:@DisplayName\("((?:[^"\\]|\\.)+)"\))?\s*(?:@\w+(?:\([^)]*\))?\s*)*void\s+(\w+)', text):
        param_name, display, method = m.groups()
        tests.append(display or (param_name and f"{method}: {param_name}") or method)
    backend_count += len(tests)
    out.append(f"### {title}")
    out.append(f"`{rel}`")
    out.append("")
    out += [f"- {t.replace(chr(92) + chr(34), chr(34))}" for t in tests]
    out.append("")

out += ["## Frontend (Vitest + Testing Library, `frontend/src`)", ""]
frontend_count = 0
for path in sorted((ROOT / "frontend/src").rglob("*.test.js*")):
    text = path.read_text()
    out.append(f"### `{path.relative_to(ROOT).as_posix()}`")
    out.append("")
    for m in re.finditer(r"(describe|it)\(\s*'((?:[^'\\]|\\.)+)'", text):
        kind, name = m.groups()
        if kind == "describe":
            out.append(f"**{name}**")
            out.append("")
        else:
            frontend_count += 1
            out.append(f"- {name}")
    out.append("")

out += ["## End-to-end (Playwright, `e2e/tests`)", "",
        "Whole user journeys in Chromium against the real jar on an in-memory database; each test",
        "creates its own uniquely named data through the API, then works through the UI.", ""]
e2e_count = 0
for path in sorted((ROOT / "e2e/tests").glob("*.spec.js")):
    text = path.read_text()
    out.append(f"### `{path.relative_to(ROOT).as_posix()}`")
    out.append("")
    for m in re.finditer(r"\btest\(\s*'((?:[^'\\]|\\.)+)'", text):
        e2e_count += 1
        out.append(f"- {m.group(1)}")
    out.append("")

out.insert(8, f"Totals: {backend_count} backend test methods (parameterised ones run once per case), "
              f"{frontend_count} frontend tests, {e2e_count} end-to-end journeys.")
out.insert(9, "")
(ROOT / "docs/TESTING.md").write_text("\n".join(out).rstrip() + "\n")
print(f"docs/TESTING.md: {backend_count} backend, {frontend_count} frontend, {e2e_count} e2e")
